<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">report </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> supervise([(</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;t-1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;billing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">), (</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;t-2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;unknown&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">), (</span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;t-3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#96D0FF;">&quot;no-evidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">)])</span></span>
